import 'dart:convert';import 'package:crypto/crypto.dart';import 'package:http/http.dart' as http;import '../data/astro_repository.dart';
class ContentUpdateResult{const ContentUpdateResult(this.version,this.files);final String version;final int files;}
class StaticContentService{StaticContentService({http.Client? client}):_client=client??http.Client();final http.Client _client;
Future<ContentUpdateResult> checkAndUpdate(Uri manifestUri)async{if(manifestUri.scheme!='https'||manifestUri.host!='raw.githubusercontent.com'||manifestUri.userInfo.isNotEmpty)throw const FormatException('Use a public HTTPS raw.githubusercontent.com manifest URL.');final raw=await _get(manifestUri,256*1024);final decoded=jsonDecode(utf8.decode(raw));if(decoded is! Map<String,dynamic>||decoded['schema_version']!=1)throw const FormatException('Unsupported manifest schema.');final version=decoded['content_version'],files=decoded['files'];if(version is! String||version.trim().isEmpty||files is! List||files.isEmpty)throw const FormatException('Manifest version or files missing.');final staged=<({String path,String payload})>[];var totalBytes=0;for(final item in files){if(item is! Map)throw const FormatException('Invalid manifest entry.');final f=Map<String,dynamic>.from(item);final path=f['path'],hash=f['sha256'],size=f['size_bytes'];if(path is! String||!_safe(path)||hash is! String||!RegExp(r'^[a-fA-F0-9]{64}$').hasMatch(hash)||size is! int||size<1||size>1048576)throw const FormatException('Invalid content path, size or checksum.');final uri=manifestUri.resolve(path);if(uri.scheme!=manifestUri.scheme||uri.host!=manifestUri.host)throw const FormatException('Content host mismatch.');totalBytes+=size;if(totalBytes>5*1024*1024)throw const FormatException('Manifest exceeds the 5 MB total download budget.');final bytes=await _get(uri,size);if(bytes.length!=size||sha256.convert(bytes).toString().toLowerCase()!=hash.toLowerCase())throw const FormatException('Content checksum or size mismatch.');final payload=utf8.decode(bytes);final doc=jsonDecode(payload);if(doc is! Map<String,dynamic>||doc['schema_version']!=1)throw const FormatException('Unsupported pack schema.');if(doc['pack_type']=='daily_horoscopes')_validateDaily(doc);if(doc['pack_type']=='lunar_events')_validateLunar(doc);staged.add((path:path,payload:payload));}await AstroRepository.instance.activateContentBatch(version,staged);for(final f in staged){final doc=jsonDecode(f.payload);if(doc is Map&&doc['pack_type']=='lunar_events'){await AstroRepository.instance.cacheLunarEvents((doc['events'] as List).map((e)=>Map<String,dynamic>.from(e)).toList());}}await AstroRepository.instance.setSetting('content_version',version);await AstroRepository.instance.setSetting('content_last_success',DateTime.now().toUtc().toIso8601String());return ContentUpdateResult(version,staged.length);}
void _validateDaily(Map<String,dynamic> d){if(d['date'] is! String||d['editorial_timezone'] is! String||DateTime.tryParse(d['date'] as String)==null)throw const FormatException('Daily pack needs a valid date and editorial timezone.');final rows=d['readings'];if(rows is! List)throw const FormatException('Missing readings.');final signs=<String>{},keys=<String>{};for(final row in rows){if(row is! Map)throw const FormatException('Invalid reading row.');final r=Map<String,dynamic>.from(row);final id=r['id'],sign=r['sign_id'],body=r['body'],title=r['title'],status=r['status']??'published',start=r['period_start'],end=r['period_end'],period=r['period_type']??'daily';if(id is! String||sign is! String||body is! String||body.trim().isEmpty||title is! String||start is! String||end is! String||DateTime.tryParse(start)==null||DateTime.tryParse(end)==null||period!='daily'||status!='published'||!['aries','taurus','gemini','cancer','leo','virgo','libra','scorpio','sagittarius','capricorn','aquarius','pisces'].contains(sign))throw const FormatException('Invalid horoscope record.');final key=sign+':'+(r['category']??'general').toString();if(!keys.add(key))throw const FormatException('Duplicate sign/category.');signs.add(sign);}if(signs.length!=12)throw const FormatException('Daily pack must cover all twelve signs.');}
void _validateLunar(Map<String,dynamic> doc){final events=doc['events'];if(events is! List)throw const FormatException('Lunar pack has no events.');final ids=<String>{};DateTime? previous;for(final raw in events){if(raw is! Map)throw const FormatException('Invalid lunar event.');final e=Map<String,dynamic>.from(raw);for(final k in ['id','phase','timestamp_utc','source_timezone','source_name','dataset_version','verified_at','source_url']){if(e[k] is! String||(e[k] as String).trim().isEmpty)throw FormatException('Lunar event is missing '+k+'.');if(k=='source_url'&&Uri.tryParse(e[k] as String)?.scheme!='https')throw const FormatException('Lunar source URLs must use HTTPS.');}final id=e['id'] as String;if(!ids.add(id))throw const FormatException('Duplicate lunar event ID.');final date=DateTime.tryParse(e['timestamp_utc'] as String);if(date==null||!date.isUtc)throw const FormatException('Lunar timestamps must be UTC.');if(previous!=null&&date.isBefore(previous))throw const FormatException('Lunar events are not chronological.');previous=date;}}
bool _safe(String p){final u=Uri.tryParse(p);return u!=null&&!u.hasScheme&&!u.hasAuthority&&!p.startsWith('/')&&!u.pathSegments.contains('..')&&!u.pathSegments.contains('.');}
Future<List<int>> _get(Uri u,int limit)async{final r=await _client.get(u).timeout(const Duration(seconds:15));if(r.statusCode!=200)throw FormatException('HTTP '+r.statusCode.toString());if(r.bodyBytes.length>limit)throw const FormatException('Content exceeds size limit.');return r.bodyBytes;}
void close()=>_client.close();}
